      <div class="panel-head">
        <h2>烧杯中的粒子</h2>
        <span class="tag" id="expTag">原实验</span>
      </div>
      <svg id="beaker" viewBox="0 0 420 370" role="img" aria-label="烧杯中的离子和沉淀示意"></svg>
      <div id="legend" class="legend"></div>
    </section>
  </div>

  <section class="panel explore-panel">
    <div class="panel-head">
      <h2>换一种试剂，曲线还一样吗？</h2>
      <span class="tag">点击对比，再拖动滑块</span>
    </div>

    <div class="exp-tabs" id="expTabs"></div>

    <div class="step-row">
      <span class="step-label">原实验分步观察：</span>
      <button class="step-btn" data-t="0">初始</button>
      <button class="step-btn" data-t="2">AB 段</button>
